package prwatch

import (
	"fmt"
	"testing"
)

func TestSummarizeNilHeadSHA(t *testing.T) {
	head := "abc1234"

	tests := []struct {
		name string
		snap *Snapshot
		want string
	}{
		{
			name: "head present",
			snap: &Snapshot{Title: "Fix the watch loop", HeadSHA: &head},
			want: "Fix the watch loop at abc1234",
		},
		{
			name: "head missing",
			snap: &Snapshot{Title: "Fix the watch loop"},
			want: "Fix the watch loop at unknown",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := summarizeNoPanic(tt.snap)
			if err != nil {
				t.Fatalf("summarize(%+v) panicked: %v", tt.snap, err)
			}
			if got != tt.want {
				t.Errorf("summarize(%+v) = %q, want %q", tt.snap, got, tt.want)
			}
		})
	}
}

// summarizeNoPanic turns a panic into an error so a nil head fails this test
// alone instead of taking the whole test binary down with it.
func summarizeNoPanic(snap *Snapshot) (s string, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("%v", r)
		}
	}()
	return summarize(snap), nil
}

package prwatch

import (
	"strings"
	"testing"
)

// Regression test for review comment 2214477901 on PR #128: summarize
// dereferences Snapshot.HeadSHA unconditionally, so any snapshot that arrives
// with a nil head takes the whole watch loop down with a nil pointer
// dereference instead of degrading to a partial summary.
func TestSummarizeNilHeadSHA(t *testing.T) {
	defer func() {
		if r := recover(); r != nil {
			t.Fatalf("summarize panicked on a nil HeadSHA: %v", r)
		}
	}()

	got := summarize(&Snapshot{Title: "Add watch loop"})

	// Loose on purpose: the placeholder for an absent SHA is a product
	// decision that hasn't been made yet. Tighten this to an exact string
	// once the fix picks one.
	if !strings.Contains(got, "Add watch loop") {
		t.Errorf("summarize(nil head) = %q, want it to still mention the title", got)
	}
}

// Pins the behaviour the fix must not regress.
func TestSummarizeWithHeadSHA(t *testing.T) {
	sha := "0d1c2b3"

	got := summarize(&Snapshot{Title: "Add watch loop", HeadSHA: &sha})

	want := "Add watch loop at 0d1c2b3"
	if got != want {
		t.Errorf("summarize() = %q, want %q", got, want)
	}
}

